// Preparar texto transcrito del audio
const transcription = $input.first().json.text || 'No pude entender el audio';
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const firstName = $('Telegram Trigger').first().json.message.from.first_name || 'Cliente';
const username = $('Telegram Trigger').first().json.message.from.username || '';

return [{
  json: {
    chatId: chatId,
    userMessage: transcription,
    firstName: firstName,
    username: username,
    messageType: 'voice',
    sessionId: `telegram_${chatId}`
  }
}];

// Preparar mensaje de texto
const message = $input.first().json.message;
const chatId = message.chat.id;
const text = message.text || '';
const firstName = message.from.first_name || 'Cliente';
const username = message.from.username || '';

return [{
  json: {
    chatId: chatId,
    userMessage: text,
    firstName: firstName,
    username: username,
    messageType: 'text',
    sessionId: `telegram_${chatId}`
  }
}];

// Preparar callback query (botones inline)
const callback = $input.first().json.callback_query;
const chatId = callback.message.chat.id;
const data = callback.data;
const firstName = callback.from.first_name || 'Cliente';
const username = callback.from.username || '';

return [{
  json: {
    chatId: chatId,
    userMessage: data,
    firstName: firstName,
    username: username,
    messageType: 'callback',
    sessionId: `telegram_${chatId}`
  }
}];

// Herramienta para guardar citas usando staticData de n8n
const staticData = $getWorkflowStaticData('global');

if (!staticData.citas) {
  staticData.citas = [];
}

// Extraer datos de la query del agente
const queryStr = $input.first().json.query || '{}';
let citaData;
try {
  citaData = JSON.parse(queryStr);
} catch(e) {
  citaData = { raw: queryStr };
}

// Crear nueva cita
const nuevaCita = {
  id: `CITA-${Date.now()}`,
  cliente: citaData.cliente || citaData.nombre || 'Sin nombre',
  servicio: citaData.servicio || 'Sin especificar',
  barbero: citaData.barbero || 'Sin preferencia',
  fecha: citaData.fecha || 'Sin especificar',
  hora: citaData.hora || 'Sin especificar',
  telefono: citaData.telefono || 'Sin especificar',
  precio: citaData.precio || 'Sin especificar',
  estado: 'confirmada',
  creadaEn: new Date().toISOString()
};

staticData.citas.push(nuevaCita);

return `Cita guardada exitosamente con ID: ${nuevaCita.id}. Cliente: ${nuevaCita.cliente}, Servicio: ${nuevaCita.servicio}, Barbero: ${nuevaCita.barbero}, Fecha: ${nuevaCita.fecha}, Hora: ${nuevaCita.hora}.`;

// Herramienta para consultar citas y disponibilidad
const staticData = $getWorkflowStaticData('global');
const citas = staticData.citas || [];

const queryStr = $input.first().json.query || '';

// Filtrar citas activas
const citasActivas = citas.filter(c => c.estado === 'confirmada');

if (citasActivas.length === 0) {
  return 'No hay citas registradas. Todos los horarios estan disponibles.';
}

// Intentar filtrar por query si se proporcionó
let resultado = citasActivas;
if (queryStr) {
  resultado = citasActivas.filter(c => {
    const query = queryStr.toLowerCase();
    return (c.fecha && c.fecha.toLowerCase().includes(query)) ||
           (c.barbero && c.barbero.toLowerCase().includes(query)) ||
           (c.cliente && c.cliente.toLowerCase().includes(query));
  });
}

if (resultado.length === 0) {
  return `No se encontraron citas para "${queryStr}". Todos los horarios estan disponibles para esa busqueda.`;
}

// Formatear resultado
const horariosOcupados = resultado.map(c => 
  `- ${c.fecha} a las ${c.hora}: ${c.cliente} con ${c.barbero} (${c.servicio})`
).join('\n');

const horariosBase = ['8:00', '8:45', '9:30', '10:15', '11:00', '11:45', '12:30', '13:15', '14:00', '14:45', '15:30', '16:15', '17:00'];
const horasOcupadas = resultado.map(c => c.hora);
const horasDisponibles = horariosBase.filter(h => !horasOcupadas.includes(h));

return `Citas encontradas:\n${horariosOcupados}\n\nHorarios disponibles: ${horasDisponibles.join(', ') || 'Ninguno disponible'}`;

// Herramienta para cancelar citas
const staticData = $getWorkflowStaticData('global');
const citas = staticData.citas || [];

const queryStr = ($input.first().json.query || '').toLowerCase();

// Buscar la cita
const index = citas.findIndex(c => {
  if (c.estado !== 'confirmada') return false;
  return (c.cliente && c.cliente.toLowerCase().includes(queryStr)) ||
         (c.id && c.id.toLowerCase().includes(queryStr));
});

if (index === -1) {
  return `No se encontro una cita activa para "${queryStr}". Verifica el nombre del cliente o ID de cita.`;
}

const citaCancelada = citas[index];
citas[index].estado = 'cancelada';
citas[index].canceladaEn = new Date().toISOString();

return `Cita cancelada exitosamente: Cliente: ${citaCancelada.cliente}, Servicio: ${citaCancelada.servicio}, Fecha: ${citaCancelada.fecha}, Hora: ${citaCancelada.hora}, Barbero: ${citaCancelada.barbero}`;

// Formatear y preparar la respuesta para Telegram
const aiResponse = $input.first().json.output || $input.first().json.text || 'Lo siento, no pude procesar tu mensaje. Podrías intentar de nuevo?';

// Obtener chatId de los nodos anteriores
let chatId;
try {
  chatId = $('Preparar Texto').first().json.chatId;
} catch(e) {
  try {
    chatId = $('Preparar Audio Transcrito').first().json.chatId;
  } catch(e2) {
    try {
      chatId = $('Preparar Callback').first().json.chatId;
    } catch(e3) {
      chatId = null;
    }
  }
}

// Limitar longitud del mensaje (Telegram max 4096 chars)
let finalMessage = aiResponse;
if (finalMessage.length > 4000) {
  finalMessage = finalMessage.substring(0, 4000) + '\n\n... (mensaje recortado)';
}

return [{
  json: {
    chatId: chatId,
    text: finalMessage
  }
}];

// Extraer chatId para notificación de audio
const chatId = $input.first().json.message.chat.id;
return [{ json: { chatId: chatId } }];
